overloading.ino<pre><code>// same name, different parameter lists: overloading
float area(float r)          { return PI * r * r; }   // circle
float area(float w, float h) { return w * h; }        // rectangle
float area(float a, float b, float c) {               // triangle (Heron)
  float s = (a + b + c) / 2;
  return sqrt(s * (s - a) * (s - b) * (s - c));
}
// default values: the caller may leave the last parameters out
void blink(int pin, int times = 1, int ms = 200) {
  for (int i = 0; i &lt; times; i++) {
    digitalWrite(pin, HIGH); delay(ms); digitalWrite(pin, LOW); delay(ms);
  }
}
void setup() {
  Serial.begin(115200);
  pinMode(23, OUTPUT);
  Serial.println(area(1.0));            // circle:    3.14
  Serial.println(area(2.0, 3.0));       // rectangle: 6.00
  Serial.println(area(3.0, 4.0, 5.0));  // triangle:  6.00
  blink(23);  blink(23, 3);  blink(23, 3, 50);
}
void loop() {}
</code></pre> <p>Download this example</p> <ul> <li> <p>Overloading: one name, several versions. The compiler picks the version by the number and types of the arguments.</p> </li> <li> <p>Default parameters: values used when the caller leaves them out; they must be the last parameters.</p> </li> </ul> <p>Ambiguous calls</p> <p><code>area(2, 3)</code> with <code>int</code> arguments still works (converted to <code>float</code>), but two overloads that fit equally well give a compile error.</p>

grades.ino<pre><code>float average(const float g[], int n) {        // array in, float out
  float sum = 0;
  for (int i = 0; i &lt; n; i++) sum += g[i];
  return sum / n;
}
bool passed(float grade) { return grade &gt;= 5.5; }   // float in, bool out
char letter(float grade) {                          // float in, char out
  if (grade &gt;= 8.0) return 'A';
  if (grade &gt;= 7.0) return 'B';
  return grade &gt;= 5.5 ? 'C' : 'F';
}
String verdict(float grade) { return passed(grade) ? "pass" : "fail"; }
void setup() {
  Serial.begin(115200);
  float grades[] = {7.5, 5.0, 8.2, 6.4, 9.1};
  int n = sizeof(grades) / sizeof(grades[0]);
  for (int i = 0; i &lt; n; i++)
    Serial.printf("student %d: %.1f %c %s\n", i + 1, grades[i],
                  letter(grades[i]), verdict(grades[i]).c_str());
  Serial.printf("group average: %.2f\n", average(grades, n));
}
void loop() {}
</code></pre> <p>Download this example</p> <ul> <li> <p>Four functions, four return types: <code>float</code>, <code>bool</code>, <code>char</code>, <code>String</code>.</p> </li> <li> <p>An array parameter needs its length as a second parameter: the function cannot know it.</p> </li> <li> <p><code>const</code>: the function promises not to change the grades.</p> </li> <li> <p><code>.c_str()</code> turns a <code>String</code> into text for <code>printf</code>.</p> </li> </ul> <p>Dutch grades</p> <p>Scale 1–10, pass from 5.5. The letters are only an example of a <code>char</code> result.</p>

references.ino<pre><code>// &amp; = reference: the function works on the caller's variable
void rectangle(float w, float h, float &amp;area, float &amp;perimeter) {
  area = w * h;
  perimeter = 2 * (w + h);
}
void minMax(const float v[], int n, float &amp;lo, float &amp;hi) {
  lo = hi = v[0];
  for (int i = 1; i &lt; n; i++) {
    if (v[i] &lt; lo) lo = v[i];
    if (v[i] &gt; hi) hi = v[i];
  }
}
void setup() {
  Serial.begin(115200);
  float a, p;
  rectangle(3, 4, a, p);                        // a = 12, p = 14
  Serial.printf("area %.1f, perimeter %.1f\n", a, p);
  float grades[] = {7.5, 5.0, 8.2, 6.4, 9.1};
  float lowest, highest;
  minMax(grades, 5, lowest, highest);
  Serial.printf("lowest %.1f, highest %.1f\n", lowest, highest);
}
void loop() {}
</code></pre> <p>Download this example</p> <p></p> <ul> <li> <p>By value (default): the function gets a copy; changes stay inside.</p> </li> <li> <p>By reference (<code>&amp;</code>): the function works on the caller’s variable: a way to return several results.</p> </li> <li> <p>Arrays are always passed as an address: use <code>const</code> if the function must not change them.</p> </li> </ul>

