void setup() { Serial.begin(115200); pinMode(KEY1, INPUT); }

void loop() {
  bool key = digitalRead(KEY1);
  if (key == HIGH &amp;&amp; lastKey == LOW) onButton();   // rising edge
  lastKey = key;
  delay(20);                                       // simple debounce
}
