  {"Anna", 4512, 7.8}, {"Bram", 4519, 5.2},
  {"Chen", 4530, 8.9}, {"Dewi", 4544, 6.1} };
const int N = sizeof(group) / sizeof(group[0]);
float averageGrade(const Student g[], int n) {
  float sum = 0;
  for (int i = 0; i &lt; n; i++) sum += g[i].grade;
  return sum / n;
