}
Point center(const Rectangle &amp;r) {      // returns a struct
  return { r.corner.x + r.width / 2, r.corner.y + r.height / 2 };
}
float distance(Point a, Point b) {      // by value: small struct
  return sqrt(sq(a.x - b.x) + sq(a.y - b.y));
}
void setup() {
  Serial.begin(115200);
  Rectangle box = { {0, 0}, 4, 2 };      // corner (0,0), 4 x 2
  Point c = center(box);                 // (2, 1)
  Serial.printf("area %.1f, center (%.1f, %.1f)\n", area(box), c.x, c.y);
  Serial.printf("distance to origin %.2f\n", distance(c, {0, 0}));
}
void loop() {}
</code></pre> <p>Download this example</p> <ul> <li> <p>A struct can be a parameter and a return value: an easy way to return several values at once.</p> </li> <li> <p>Structs can contain other structs: <code>box.corner.x</code>.</p> </li> <li> <p>Large structs: pass as <code>const Type &amp;</code>: no copy, and the function cannot change it.</p> </li> <li> <p><code>sq(x)</code> is the Arduino function for \(x^2\).</p> </li> </ul> <p></p> <p>Sources: Passing and returning structs</p>

led_structs.ino<pre><code>struct Led {
  int pin;
  unsigned long interval;      // ms
  unsigned long last = 0;      // default values
  bool on = false;
};
Led leds[] = {                 // pin, interval
  {23, 250}, {22, 500}, {21, 1000}, {4, 2000},
};
const int N = sizeof(leds) / sizeof(leds[0]);
void update(Led &amp;led) {        // reference: changes the LED
  if (millis() - led.last &gt;= led.interval) {
    led.last = millis();
    led.on = !led.on;
    digitalWrite(led.pin, led.on);
  }
}
void setup() {
  for (int i = 0; i &lt; N; i++) pinMode(leds[i].pin, OUTPUT);
}
void loop() {
  for (int i = 0; i &lt; N; i++) update(leds[i]);
}
</code></pre> <p>Download this example</p> <ul> <li> <p>Every LED keeps its own pin, speed, time stamp and state.</p> </li> <li> <p>Four LEDs, four speeds, no <code>delay()</code>, and one small function.</p> </li> <li> <p>A fifth LED: add one line to the array.</p> </li> <li> <p>Members can have default values (<code>last = 0</code>).</p> </li> </ul> <p>Compare</p> <p>The Several independent timers example needed separate variables for every LED. A struct makes the pattern scale.</p>

