timer_blink.ino<pre><code>const int LED_PIN = 22;
const uint32_t TIMER_FREQUENCY = 10000;
const uint64_t ALARM_TICKS = 20000;
hw_timer_t *timer = nullptr;

void ARDUINO_ISR_ATTR onTimer() {
  digitalWrite(LED_PIN, !digitalRead(LED_PIN));
}

void setup() {
  Serial.begin(115200);
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LED_PIN, LOW);

  timer = timerBegin(TIMER_FREQUENCY);
  if (timer == nullptr) {
    Serial.println("Timer allocation failed");
    return;
  }
  timerAttachInterrupt(timer, &amp;onTimer);
  timerAlarm(timer, ALARM_TICKS, true, 0);
}

void loop() {
  // Other non-blocking work can run here.
}
</code></pre> <p>Change <code>LED_PIN</code> to match your wiring. On the course carrier, GPIO22 controls one of the LEDs.</p> Setting Value Meaning Tick frequency <code>10000</code> 10,000 ticks per second Alarm value <code>20000</code> Interrupt after 20,000 ticks Auto-reload <code>true</code> Repeat the alarm Reload count <code>0</code> Repeat without a count limit
